from collections import deque

def main():
    n = int(sys.stdin.readline())
    p = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n + 1)]

    for i in range(1, n + 1):
        line = sys.stdin.readline().strip()
        for j in range(1, n + 1):
            if line[j - 1] == '1':
                adj[i].append(j)

    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            q = deque()
            q.append(i)
            visited[i] = True
            component = []
            while q:
                u = q.popleft()
                component.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        q.append(v)
            components.append(component)

    for component in components:
        sorted_pos = sorted(component)
        elements = [p[pos - 1] for pos in sorted_pos]
        elements.sort()
        for idx in range(len(sorted_pos)):
            p[sorted_pos[idx] - 1] = elements[idx]

