import sys

class Node:
    def __init__(self, key):
        self.key = key
        self.prev = None
        self.next = None

def main():
    n = int(sys.stdin.readline())
    head = None
    tail = None

    for _ in range(n):
        line = sys.stdin.readline().strip()
        if line.startswith('insert '):
            x = int(line.split()[1])
            new_node = Node(x)
            if not head:
                head = new_node
                tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif line.startswith('delete '):
            x = int(line.split()[1])
            current = head
            found = False
            while current:
                if current.key == x:
                    found = True
                    break
                current = current.next
            if found:
                prev_node = current.prev
                next_node = current.next
                if prev_node:
                    prev_node.next = next_node
                else:
                    head = next_node
                if next_node:
                    next_node.prev = prev_node
                else:
                    tail = prev_node
        elif line == 'deleteFirst':
            if head:
                prev_node = head.prev
                if prev_node is None:
                    head = None
                    tail = None
                else:
                    head = head.next
                    head.prev = None
        elif line == 'deleteLast':
            if tail:
                next_node = tail.next
                if next_node is None:
                    head = None
                    tail = None
                else:
                    tail = tail.prev
                    tail.next = None

    result = []
    current = head
    while current:
        result.append(str(current.key))
        current = current.next
    print(' '.join(result))

